%% |scalar fields are last-write-wins| — laws/search_query.lawspec:487
%% A built query's size is the last size/2 call's, or new/2's :size
%%     option when no call sets one, or 10 when neither does. Its min_score is
%%     what the last min_score/2 call set, nothing when that call passed nil,
%%     and otherwise new/2's :min_score option, or nothing. Clause builders
%%     change neither, and no call changes the index.
%% for all (start :: cake.laws.search_query::type::Start) (mix :: cake.laws.search_query::type::CallMix) => match (builtQuery start (callsOf mix)) { cake.laws.search_query::type::BuiltQuery::BuiltQuery lawspecFieldindex lawspecFieldsize lawspecFieldminScore lawspecFieldmusts lawspecFieldshoulds lawspecFieldfilters -> lawspecFieldindex } = match (start) { cake.laws.search_query::type::Start::Start lawspecFieldindex lawspecFieldsize lawspecFieldminScore -> lawspecFieldindex } and match (builtQuery start (callsOf mix)) { cake.laws.search_query::type::BuiltQuery::BuiltQuery lawspecFieldindex lawspecFieldsize lawspecFieldminScore lawspecFieldmusts lawspecFieldshoulds lawspecFieldfilters -> lawspecFieldsize } = sizeAfter (startingSize start) (callsOf mix) and match (builtQuery start (callsOf mix)) { cake.laws.search_query::type::BuiltQuery::BuiltQuery lawspecFieldindex lawspecFieldsize lawspecFieldminScore lawspecFieldmusts lawspecFieldshoulds lawspecFieldfilters -> lawspecFieldminScore } = minScoreAfter (startingMinScore start) (callsOf mix) end for all
law_scalar_fields_are_last_write_wins(Schema, Symbols, [Start, Mix]) ->
    ((lawspec_beam_runtime:assert_equal(
        lawspec_beam_schema:match(
            lawspec_definitions:built_query(
                Schema,
                Symbols,
                Start,
                lawspec_definitions:calls_of(Schema, Symbols, Mix)
            ),
            #{
                <<"cake.laws.search_query::type::BuiltQuery::BuiltQuery">> => fun(
                    [Index, _Size, _MinScore, _Musts, _Shoulds, _Filters]
                ) ->
                    Index
                end
            }
        ),
        lawspec_beam_schema:match(
            Start,
            #{
                <<"cake.laws.search_query::type::Start::Start">> => fun(
                    [Index, _Size, _MinScore]
                ) ->
                    Index
                end
            }
        ),
        ?LAW_SCALAR_FIELDS_ARE_LAST_WRITE_WINS
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_beam_schema:match(
                lawspec_definitions:built_query(
                    Schema,
                    Symbols,
                    Start,
                    lawspec_definitions:calls_of(Schema, Symbols, Mix)
                ),
                #{
                    <<"cake.laws.search_query::type::BuiltQuery::BuiltQuery">> => fun(
                        [_Index, Size, _MinScore, _Musts, _Shoulds, _Filters]
                    ) ->
                        Size
                    end
                }
            ),
            lawspec_definitions:size_after(
                Schema,
                Symbols,
                lawspec_definitions:starting_size(Schema, Symbols, Start),
                lawspec_definitions:calls_of(Schema, Symbols, Mix)
            ),
            ?LAW_SCALAR_FIELDS_ARE_LAST_WRITE_WINS
        )) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_beam_schema:match(
                lawspec_definitions:built_query(
                    Schema,
                    Symbols,
                    Start,
                    lawspec_definitions:calls_of(Schema, Symbols, Mix)
                ),
                #{
                    <<"cake.laws.search_query::type::BuiltQuery::BuiltQuery">> => fun(
                        [_Index, _Size, MinScore, _Musts, _Shoulds, _Filters]
                    ) ->
                        MinScore
                    end
                }
            ),
            lawspec_definitions:min_score_after(
                Schema,
                Symbols,
                lawspec_definitions:starting_min_score(Schema, Symbols, Start),
                lawspec_definitions:calls_of(Schema, Symbols, Mix)
            ),
            ?LAW_SCALAR_FIELDS_ARE_LAST_WRITE_WINS
        )).

