%% |reordering the calls keeps each list's clauses| — laws/search_query.lawspec:549
%% Builder calls in any other order build a query whose must, should and
%%     filter hold the same clauses, each as many times, in some order. Only
%%     the clause order and the scalars depend on the order of the calls.
%% for all (start :: cake.laws.search_query::type::Start) (mix :: cake.laws.search_query::type::CallMix) (picks :: List (BigUInt)) => sameClauses (builtQuery start (reordered (callsOf mix) picks)) (builtQuery start (callsOf mix)) = true end for all
law_reordering_the_calls_keeps_each_list_s_clauses(Schema, Symbols, [Start, Mix, Picks]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:same_clauses(
            Schema,
            Symbols,
            lawspec_definitions:built_query(
                Schema,
                Symbols,
                Start,
                lawspec_definitions:reordered(
                    Schema,
                    Symbols,
                    lawspec_definitions:calls_of(Schema, Symbols, Mix),
                    Picks
                )
            ),
            lawspec_definitions:built_query(
                Schema,
                Symbols,
                Start,
                lawspec_definitions:calls_of(Schema, Symbols, Mix)
            )
        ),
        true,
        ?LAW_REORDERING_THE_CALLS_KEEPS_EACH_LIST_S_CLAUSES
    ).

