-define(LAW_A_KNN_CLAUSE_CARRIES_EF_SEARCH_ONLY_WHEN_THE,
    <<"cake.laws.search_query::|a knn clause carries ef_search only when the call gives one|">>
).

%% |a knn clause carries ef_search only when the call gives one| — laws/search_query.lawspec:579
%% knn/5 adds one clause to must: the field, holding the vector and k.
%%     Given an :ef_search it adds method_parameters with that ef_search and
%%     nothing else; given none, the clause has no method_parameters at all.
%% for all (start :: cake.laws.search_query::type::Start) (clause :: cake.laws.search_query::type::KnnClause) => match (builtQuery start (List::Cons(cake.laws.search_query::type::BuilderCall::Knn(clause), List::Nil()))) { cake.laws.search_query::type::BuiltQuery::BuiltQuery lawspecFieldindex lawspecFieldsize lawspecFieldminScore lawspecFieldmusts lawspecFieldshoulds lawspecFieldfilters -> lawspecFieldmusts } = List::Cons(clause, List::Nil()) end for all
law_a_knn_clause_carries_ef_search_only_when_the(Schema, Symbols, [Start, Clause]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_schema:match(
            lawspec_definitions:built_query(
                Schema,
                Symbols,
                Start,
                make_cons_4([make_knn([Clause], Schema), []], Schema)
            ),
            #{
                <<"cake.laws.search_query::type::BuiltQuery::BuiltQuery">> => fun(
                    [_Index, _Size, _MinScore, Musts, _Shoulds, _Filters]
                ) ->
                    Musts
                end
            }
        ),
        make_cons_5([Clause, []], Schema),
        ?LAW_A_KNN_CLAUSE_CARRIES_EF_SEARCH_ONLY_WHEN_THE
    ).

