%% |a knn clause carries ef_search only when the call gives one| example |no ef_search| — laws/search_query.lawspec:597
law_a_knn_clause_carries_ef_search_only_when_the__no_ef_search() ->
    {Schema, Symbols} = lawspec_data:context(),
    Start = make_start([<<"docs">>, make_absent([], Schema), make_absent_2([], Schema)], Schema),
    Clause = make_knn_clause([<<"embedding">>, [10, -20, 30], 10, make_absent([], Schema)], Schema),
    lawspec_beam_runtime:require(
        law_a_knn_clause_carries_ef_search_only_when_the(Schema, Symbols, [Start, Clause]),
        ?LAW_A_KNN_CLAUSE_CARRIES_EF_SEARCH_ONLY_WHEN_THE
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_schema:match(
            lawspec_definitions:built_query(
                Schema,
                Symbols,
                Start,
                make_cons_4([make_knn([Clause], Schema), []], Schema)
            ),
            #{
                <<"cake.laws.search_query::type::BuiltQuery::BuiltQuery">> => fun(
                    [_Index, _Size, _MinScore, Musts, _Shoulds, _Filters]
                ) ->
                    Musts
                end
            }
        ),
        make_cons_5(
            [
                make_knn_clause(
                    [<<"embedding">>, [10, -20, 30], 10, make_absent([], Schema)],
                    Schema
                ),
                []
            ],
            Schema
        ),
        <<"|a knn clause carries ef_search only when the call gives one| example |no ef_search| — laws/search_query.lawspec:597"/utf8>>
    ).

