-define(LAW_THE_QUERY_MAP_KEEPS_THE_QUERY_S_SIZE_MIN_SCORE,
    <<"cake.laws.search_query::|the query map keeps the query's size, min_score and clauses|">>
).

%% |the query map keeps the query's size, min_score and clauses| — laws/search_query.lawspec:622
%% to_query_map/1 returns a map of one shape: the query's size, and
%%     under query.bool its must, should and filter, each holding the query's
%%     clauses, as many times each as the query holds them. The map has a
%%     min_score exactly when the query's is not nil, and then it is the
%%     query's.
%% for all (start :: cake.laws.search_query::type::Start) (mix :: cake.laws.search_query::type::CallMix) => keepsQuery (queryMap start (callsOf mix)) (builtQuery start (callsOf mix)) = true end for all
law_the_query_map_keeps_the_query_s_size_min_score(Schema, Symbols, [Start, Mix]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:keeps_query(
            Schema,
            Symbols,
            lawspec_definitions:query_map(
                Schema,
                Symbols,
                Start,
                lawspec_definitions:calls_of(Schema, Symbols, Mix)
            ),
            lawspec_definitions:built_query(
                Schema,
                Symbols,
                Start,
                lawspec_definitions:calls_of(Schema, Symbols, Mix)
            )
        ),
        true,
        ?LAW_THE_QUERY_MAP_KEEPS_THE_QUERY_S_SIZE_MIN_SCORE
    ).

