%% |the query map lists clauses in insertion order| — laws/search_query.lawspec:678
%% to_query_map/1 of a built query is the reference model's map: the
%%     scalars as last written, and must, should and filter each holding the
%%     clauses of its kind in the order the builders were called, first call
%%     first. A match/4 call that gives no boost adds a clause with a boost of
%%     1.0.
%% for all (start :: cake.laws.search_query::type::Start) (mix :: cake.laws.search_query::type::CallMix) => queryMap start (callsOf mix) = queryMapOf start (callsOf mix) end for all
law_the_query_map_lists_clauses_in_insertion_order(Schema, Symbols, [Start, Mix]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:query_map(
            Schema,
            Symbols,
            Start,
            lawspec_definitions:calls_of(Schema, Symbols, Mix)
        ),
        lawspec_definitions:query_map_of(
            Schema,
            Symbols,
            Start,
            lawspec_definitions:calls_of(Schema, Symbols, Mix)
        ),
        ?LAW_THE_QUERY_MAP_LISTS_CLAUSES_IN_INSERTION_ORDER
    ).

